package com.cuupe.backend.modules.evaluation.controller;
import com.cuupe.backend.common.Result; import com.cuupe.backend.modules.evaluation.entity.EvaluationCase; import com.cuupe.backend.modules.evaluation.mapper.EvaluationCaseMapper; import com.cuupe.backend.modules.notification.service.NotificationService; import com.cuupe.backend.modules.user.security.UserLoginByPassword; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/workspaces/{workspaceId}/evaluation-cases") @RequiredArgsConstructor public class EvaluationCaseController { private final EvaluationCaseMapper mapper; private final NotificationService notificationService;
 @GetMapping public Result<List<EvaluationCase>> list(@PathVariable Long workspaceId,Authentication auth){return Result.success(mapper.findByWorkspace(workspaceId,userId(auth)));}
 @PostMapping public Result<EvaluationCase> create(@PathVariable Long workspaceId,@Valid @RequestBody CaseRequest request,Authentication auth){EvaluationCase item=new EvaluationCase();item.setWorkspaceId(workspaceId);item.setProjectId(request.projectId());item.setQuery(request.query());item.setExpectedAnswer(request.expectedAnswer());item.setCreatedBy(userId(auth));mapper.insert(item);notificationService.create(workspaceId,userId(auth),request.projectId(),"evaluation","评估用例已创建","新的评估用例已加入评估集。","project-evaluation");return Result.success(item);}
 private Long userId(Authentication a){return ((UserLoginByPassword)a.getPrincipal()).getId();} public record CaseRequest(Long projectId,@NotBlank String query,String expectedAnswer){}
}
